class TrieNode:
    """Represent a single node in a trie."""

    def __init__(self) -> None:
        """Initialize an empty node with no children."""
        self.children: dict[str, TrieNode] = {}
        self.is_end_of_word: bool = False


class Trie:
    """Store words in a prefix tree."""

    def __init__(self) -> None:
        """Initialize an empty trie."""
        self.root: TrieNode = TrieNode()
        self._word_count: int = 0

    def insert(self, word: str) -> None:
        """Insert a word, including an empty string, into the trie."""
        node = self.root

        for character in word:
            if character not in node.children:
                node.children[character] = TrieNode()
            node = node.children[character]

        if not node.is_end_of_word:
            node.is_end_of_word = True
            self._word_count += 1

    def search(self, word: str) -> bool:
        """Return whether an exact complete word exists in the trie."""
        node = self.root

        for character in word:
            if character not in node.children:
                return False
            node = node.children[character]

        return node.is_end_of_word

    def starts_with(self, prefix: str) -> bool:
        """Return whether any inserted word begins with the prefix."""
        if not prefix:
            return self._word_count > 0

        node = self.root

        for character in prefix:
            if character not in node.children:
                return False
            node = node.children[character]

        return True

    def autocomplete(
        self, prefix: str, max_results: int = 5
    ) -> list[str]:
        """Return alphabetically sorted completions using depth-first search."""
        if max_results <= 0:
            return []

        node = self.root

        for character in prefix:
            if character not in node.children:
                return []
            node = node.children[character]

        results: list[str] = []

        def dfs(current_node: TrieNode, current_word: str) -> None:
            """Collect completions from the current trie node."""
            if len(results) >= max_results:
                return

            if current_node.is_end_of_word:
                results.append(current_word)

            for character in sorted(current_node.children):
                if len(results) >= max_results:
                    break
                dfs(
                    current_node.children[character],
                    current_word + character,
                )

        dfs(node, prefix)
        return results


if __name__ == "__main__":
    trie = Trie()

    words = [
